import torch


def run(x, dim, keepdim):
    return torch.nanmedian(x, dim=dim, keepdim=keepdim)


def gen_inputs(ctx, device):
    import torch
    shape = ctx["x__shape"]
    dtype = getattr(torch, ctx["x__dtype"])
    if dtype is torch.uint8:
        inp = torch.randint(0, 101, shape, dtype=dtype, device="cpu").to(device)
    elif not dtype.is_floating_point:
        inp = torch.randint(-100, 101, shape, dtype=dtype, device="cpu").to(device)
    else:
        inp = torch.randn(shape, dtype=dtype, device=device)
        if inp.numel() > 0:
            inp.reshape(-1)[::7] = float("nan")
    return {"x": inp}


def valid(ref_outputs, sol_outputs, inputs, ctx):
    import torch
    ref_values = ref_outputs[0].detach().to("cpu")
    sol_values = sol_outputs[0].detach().to("cpu")
    sol_indices = sol_outputs[1].detach().to("cpu")
    inp = inputs[0].detach().to("cpu")
    dim = inputs[1]
    keepdim = inputs[2]
    dtype = ref_values.dtype
    if ref_values.shape != sol_values.shape:
        return {"passed": False, "message": "values shape mismatch", "metrics": {}}

    def values_close(a, b):
        if dtype.is_floating_point:
            r = a.to(torch.float64)
            s = b.to(torch.float64)
            rtol = {torch.float16: 1e-3, torch.bfloat16: 1.6e-2, torch.float32: 1.3e-6, torch.float64: 1e-7}.get(dtype, 1e-3)
            both_nan = torch.isnan(r) & torch.isnan(s)
            finite = torch.isfinite(r) & torch.isfinite(s)
            close = torch.zeros_like(r, dtype=torch.bool)
            close[finite] = (r[finite] - s[finite]).abs() <= 1e-4 + rtol * r[finite].abs()
            return bool((close | both_nan).all().item())
        return bool(torch.equal(a, b))

    if not values_close(ref_values, sol_values):
        return {"passed": False, "message": "values mismatch", "metrics": {}}
    d = dim % inp.ndim
    if sol_indices.numel() != 0:
        if not bool(torch.all(sol_indices >= 0).item()) or not bool(torch.all(sol_indices < inp.shape[d]).item()):
            return {"passed": False, "message": "indices out of range", "metrics": {}}
        gather_indices = sol_indices if keepdim else sol_indices.unsqueeze(d)
        gathered = torch.gather(inp, d, gather_indices)
        if not keepdim:
            gathered = gathered.squeeze(d)
        if not values_close(gathered, sol_values):
            return {"passed": False, "message": "gathered index values mismatch", "metrics": {}}
    return {"passed": True, "message": "", "metrics": {}}
